update oa_reimbursement_invoice
set item_id = null
where reimbursement_id = #{reimbursementId}

update oa_reimbursement_invoice
set item_id = #{itemId}
where invoice_id = #{invoiceId}
  and reimbursement_id = #{reimbursementId}

mapper.delete:
delete from oa_reimbursement_item
where item_id = #{itemId}
  and reimbursement_id = #{reimbursementId}

mapper.select:
select rec.reimbursement_id
from oa_reimbursement_invoice_recognition rec
join oa_reimbursement r
  on r.reimbursement_id = rec.reimbursement_id
where rec.invoice_number = #{invoiceNumber}
  and rec.reimbursement_id != #{reimbursementId}
  and r.status = 'approved'

  and rec.invoice_code = #{invoiceCode}

order by rec.invoice_id
limit 1

